import json, sys, os, re, datetime
src, out = sys.argv[1], sys.argv[2]
os.makedirs(out, exist_ok=True)
meta = {}
for fn in sorted(os.listdir(src)):
    if not fn.endswith('.json'): continue
    page = fn[:-5]
    d = json.load(open(os.path.join(src, fn)))
    refs = d.get('references', {})
    def inl(runs):
        s = ''
        for r in runs:
            t = r.get('type')
            if t == 'text': s += r['text']
            elif t == 'strong': s += '**' + inl(r.get('inlineContent', [])) + '**'
            elif t == 'emphasis': s += '_' + inl(r.get('inlineContent', [])) + '_'
            elif t == 'codeVoice': s += '`' + r.get('code', '') + '`'
            elif t == 'reference':
                ref = refs.get(r['identifier'], {}); s += ref.get('title', r['identifier'].split('/')[-1])
            elif t == 'link': s += r.get('title', r.get('destination', ''))
            elif 'inlineContent' in r: s += inl(r['inlineContent'])
        return s
    lines = []; changelog = []
    def blocks(bs, ind=''):
        for b in bs:
            t = b['type']
            if t == 'heading':
                lines.append(''); lines.append('#' * b['level'] + ' ' + b['text'] + '  {#' + b.get('anchor', '') + '}')
            elif t == 'paragraph':
                x = inl(b.get('inlineContent', []))
                if x.strip(): lines.append(ind + x)
            elif t in ('unorderedList', 'orderedList'):
                for it in b['items']:
                    sub = []; 
                    start = len(lines); blocks(it.get('content', []), ind + '  ')
                    if len(lines) > start: lines[start] = ind + '- ' + lines[start].lstrip()
            elif t == 'aside':
                lines.append(ind + '> [' + b.get('name', b.get('style', 'note')) + ']'); blocks(b.get('content', []), ind + '> ')
            elif t == 'table':
                for row in b['rows']:
                    cells = []
                    for c in row:
                        tmp = []; 
                        for cb in c:
                            if cb['type'] == 'paragraph': tmp.append(inl(cb.get('inlineContent', [])))
                        cells.append(' '.join(tmp))
                    lines.append(ind + '| ' + ' | '.join(cells) + ' |')
            elif t == 'tabNavigator':
                for tab in b.get('tabs', []):
                    lines.append(ind + '[tab ' + tab.get('title', '') + ']'); blocks(tab.get('content', []), ind)
            elif 'content' in b: blocks(b['content'], ind)
    for sec in d['primaryContentSections']:
        blocks(sec.get('content', []))
    txt = '\n'.join(lines)
    # change log dates
    m = txt.split('## Change log')
    dates = []
    if len(m) > 1:
        for x in re.findall(r'\| ([A-Z][a-z]+ \d{1,2}, \d{4}) \|', m[1]):
            try: dates.append(datetime.datetime.strptime(x, '%B %d, %Y').date())
            except: pass
    title = d['metadata'].get('title', page)
    abstract = inl(d.get('abstract', []))
    header = f'PAGE: {page}\nTITLE: {title}\nURL: https://developer.apple.com/design/human-interface-guidelines/{page}\nCHANGELOG_LATEST: {max(dates) if dates else "none"}\nABSTRACT: {abstract}\n'
    open(os.path.join(out, page + '.txt'), 'w').write(header + txt + '\n')
    meta[page] = {'title': title, 'changelog_latest': str(max(dates)) if dates else None, 'words': len(txt.split())}
json.dump(meta, open(os.path.join(out, '_meta.json'), 'w'), indent=1)
print(sum(v['words'] for v in meta.values()))
EOF
